package system

func addAgentRegistrationOpenAPI(spec map[string]any) {
	paths := spec["paths"].(map[string]any)
	schemas := spec["components"].(map[string]any)["schemas"].(map[string]any)
	claimGrant := "urn:workos:agent-auth:grant-type:claim"
	jwtGrant := "urn:ietf:params:oauth:grant-type:jwt-bearer"
	paths["/agent/identity"] = map[string]any{"post": op([]string{"OAuth"}, "Start human-claimed agent registration", "AI-enabled human-claimed email registration: current service_auth or the Auth.md v0.5 verified_email request alias. Creates bounded claim state for an existing account email, without looking up accounts, issuing credentials or granting access. The human must sign in, type the six-digit code, and explicitly approve team, sites and scopes. Anonymous and provider JWT/ID-JAG registration are unsupported. The legacy email alias invokes the identical native claim ceremony and returns registration_type=email-verification with HTTP 200; service_auth returns HTTP 201. Handles are stored as hashes. Public rate limits apply.", nil, nil,
		map[string]any{"required": true, "content": map[string]any{"application/json": map[string]any{"schema": map[string]any{"type": "object", "additionalProperties": false, "required": []string{"type"}, "oneOf": []any{
			map[string]any{"properties": map[string]any{"type": map[string]any{"const": "service_auth"}}, "required": []string{"login_hint"}},
			map[string]any{"properties": map[string]any{"type": map[string]any{"const": "identity_assertion"}, "assertion_type": map[string]any{"const": "verified_email"}}, "required": []string{"assertion_type", "assertion"}},
		}, "properties": map[string]any{"type": map[string]any{"enum": []string{"service_auth", "identity_assertion"}}, "assertion_type": map[string]any{"const": "verified_email"}, "assertion": map[string]any{"type": "string", "format": "email", "maxLength": 254}, "login_hint": map[string]any{"type": "string", "format": "email", "maxLength": 254}, "resource": map[string]any{"type": "string", "format": "uri"}, "scope": map[string]any{"type": "string"}}}}}},
		map[string]any{"200": jsonRefResp("Legacy email alias claim materials only", "#/components/schemas/AgentRegistration"), "201": jsonRefResp("Claim materials only; no assertion or access token", "#/components/schemas/AgentRegistration"), "400": jsonRefResp("Invalid request, method or scope", "#/components/schemas/OAuthError"), "404": desc("AI disabled"), "429": desc("Pending capacity or rate limit exceeded"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")})}
	paths["/agent/identity/claim"] = map[string]any{"post": op([]string{"OAuth"}, "Replace an unclaimed registration code", "AI-enabled service_auth retry only. Requires the original claim handle and matching email before the fifteen-minute outer expiry. Rotates the code and verification link without extending that expiry or resetting the five-attempt lockout. No anonymous registration or credential issuance.", nil, nil,
		map[string]any{"required": true, "content": map[string]any{"application/json": map[string]any{"schema": map[string]any{"type": "object", "additionalProperties": false, "required": []string{"claim_token", "email"}, "properties": map[string]any{"claim_token": map[string]any{"type": "string"}, "email": map[string]any{"type": "string", "format": "email"}}}}}},
		map[string]any{"200": jsonSchemaResp("Replacement ceremony", map[string]any{"type": "object", "required": []string{"registration_id", "status", "expires_at", "claim_attempt"}, "properties": map[string]any{"registration_id": map[string]any{"type": "string", "format": "uuid"}, "status": map[string]any{"const": "initiated"}, "expires_at": map[string]any{"type": "string", "format": "date-time"}, "claim_attempt": map[string]any{"$ref": "#/components/schemas/AgentClaimCeremony"}}}), "400": jsonRefResp("Invalid, expired, denied or claimed registration", "#/components/schemas/OAuthError"), "404": desc("AI disabled"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")})}
	paths["/oauth/agent-claim"] = map[string]any{"get": op([]string{"OAuth"}, "Open native agent consent", "AI-enabled browser bootstrap. Binds a live claim attempt to a signed browser cookie and redirects through native sign-in to explicit consent. This link alone never approves access. No-store and no-referrer.", nil,
		[]any{map[string]any{"name": "claim_attempt_token", "in": "query", "required": true, "schema": map[string]any{"type": "string"}}}, nil,
		map[string]any{"303": desc("Native sign-in and consent"), "400": jsonRefResp("Invalid or expired attempt", "#/components/schemas/OAuthError"), "404": desc("AI disabled"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")})}
	schemas["AgentClaimCeremony"] = map[string]any{"type": "object", "required": []string{"user_code", "verification_uri", "expires_in", "interval"}, "properties": map[string]any{"user_code": map[string]any{"type": "string", "pattern": "^[0-9]{6}$"}, "verification_uri": map[string]any{"type": "string", "format": "uri"}, "expires_in": map[string]any{"type": "integer", "maximum": 600}, "interval": map[string]any{"type": "integer", "minimum": 5}}}
	schemas["AgentRegistration"] = map[string]any{"type": "object", "required": []string{"registration_id", "registration_type", "claim_url", "claim_token", "claim_token_expires", "post_claim_scopes", "claim"}, "properties": map[string]any{"registration_id": map[string]any{"type": "string", "format": "uuid"}, "registration_type": map[string]any{"enum": []string{"service_auth", "email-verification"}}, "claim_url": map[string]any{"type": "string", "format": "uri"}, "claim_token": map[string]any{"type": "string"}, "claim_token_expires": map[string]any{"type": "string", "format": "date-time"}, "post_claim_scopes": map[string]any{"type": "array", "items": map[string]any{"type": "string"}}, "claim": map[string]any{"$ref": "#/components/schemas/AgentClaimCeremony"}}}
	schemas["AgentTokenResponse"] = map[string]any{"type": "object", "required": []string{"access_token", "token_type", "expires_in", "scope", "resource"}, "properties": map[string]any{"access_token": map[string]any{"type": "string"}, "token_type": map[string]any{"const": "Bearer"}, "expires_in": map[string]any{"type": "integer", "maximum": 300}, "scope": map[string]any{"type": "string"}, "resource": map[string]any{"type": "string", "format": "uri"}, "identity_assertion": map[string]any{"type": "string", "description": "Only the one-time successful claim response includes the service-signed reusable assertion."}, "assertion_expires": map[string]any{"type": "string", "format": "date-time"}}}
	token := paths["/oauth/token"].(map[string]any)["post"].(map[string]any)
	token["summary"] = "Exchange an OAuth code, refresh token or human-approved agent assertion"
	token["description"] = token["description"].(string) + " AI-enabled service_auth adds the claim poll and JWT-bearer grants. Claim polling returns authorization_pending, slow_down (add five seconds), access_denied or expired_token until a one-time success returns tokens plus the first identity_assertion. JWT-bearer accepts only HitKeep's own unexpired signed assertion and rechecks every current grant permission. Neither agent grant issues a refresh_token. Claims and assertions cannot expand scopes or switch resources."
	body := token["requestBody"].(map[string]any)["content"].(map[string]any)["application/x-www-form-urlencoded"].(map[string]any)["schema"].(map[string]any)
	body["required"] = []string{"grant_type"}
	properties := body["properties"].(map[string]any)
	properties["grant_type"].(map[string]any)["enum"] = []string{"authorization_code", "refresh_token", claimGrant, jwtGrant}
	properties["claim_token"] = map[string]any{"type": "string"}
	properties["assertion"] = map[string]any{"type": "string", "maxLength": 4096}
	alternatives := body["oneOf"].([]any)
	for _, alternative := range alternatives {
		branch := alternative.(map[string]any)
		branch["required"] = append(branch["required"].([]string), "client_id", "resource")
	}
	body["oneOf"] = append(alternatives, map[string]any{"properties": map[string]any{"grant_type": map[string]any{"const": claimGrant}}, "required": []string{"claim_token"}}, map[string]any{"properties": map[string]any{"grant_type": map[string]any{"const": jwtGrant}}, "required": []string{"assertion"}})
	token["responses"].(map[string]any)["200"] = jsonSchemaResp("OAuth token family or approved agent token without a refresh token", map[string]any{"oneOf": []any{map[string]any{"$ref": "#/components/schemas/OAuthTokenResponse"}, map[string]any{"$ref": "#/components/schemas/AgentTokenResponse"}}})
	revoke := paths["/oauth/revoke"].(map[string]any)["post"].(map[string]any)
	revoke["description"] = revoke["description"].(string) + " A server-minted agent access token requires only possession of that token and revokes that token alone; its assertion remains usable. Connected applications revocation disables the registration and every token and future assertion exchange. Ordinary code clients still require matching client_id and revoke the credential family."
	revoke["requestBody"].(map[string]any)["content"].(map[string]any)["application/x-www-form-urlencoded"].(map[string]any)["schema"].(map[string]any)["required"] = []string{"token"}
	schemas["OAuthConsent"].(map[string]any)["properties"].(map[string]any)["agent_claim"] = map[string]any{"type": "boolean", "description": "Human must enter the assistant's six-digit code before approval."}
	consent := paths["/api/oauth/consent"].(map[string]any)["post"].(map[string]any)
	consent["description"] = consent["description"].(string) + " Agent claims additionally bind the signed-in email and require claim_code on approval. Denial needs no code. Agent decisions redirect to the fixed native return page without exposing credentials; invalid codes return error=invalid_code. Billing-only consent selects a team without sites."
	consent["requestBody"].(map[string]any)["content"].(map[string]any)["application/x-www-form-urlencoded"].(map[string]any)["schema"].(map[string]any)["properties"].(map[string]any)["claim_code"] = map[string]any{"type": "string", "pattern": "^[0-9]{6}$"}
}
